def _wheel_file() -> bytes:
    lines = [
        "Wheel-Version: 1.0",
        "Generator: local-hatchling-backend",
        "Root-Is-Purelib: true",
        "Tag: py3-none-any",
        "",
    ]
    return "\n".join(lines).encode("utf-8")


def _entry_points() -> bytes:
    lines = [
        "[console_scripts]",
        "sqlformat = sqlparse.__main__:main",
        "",
    ]
    return "\n".join(lines).encode("utf-8")


def _hash_bytes(data: bytes) -> str:
    digest = hashlib.sha256(data).digest()
    return base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")


def _record_rows(files: Sequence[Tuple[str, bytes]]) -> bytes:
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    for name, data in files:
        writer.writerow((name, f"sha256={_hash_bytes(data)}", str(len(data))))
    writer.writerow((f"{_dist_info_dir()}/RECORD", "", ""))
    return buffer.getvalue().encode("utf-8")


def _iter_package_files() -> Iterator[Tuple[str, bytes]]:
    for path in sorted(PACKAGE_DIR.rglob("*")):
        if path.is_dir():
            continue
        relpath = path.relative_to(ROOT).as_posix()
        yield relpath, path.read_bytes()


def _write_wheel(
    wheel_directory: str,
    contents: Iterable[Tuple[str, bytes]],
) -> str:
    wheel_dir = Path(wheel_directory)
    wheel_dir.mkdir(parents=True, exist_ok=True)
    wheel_path = wheel_dir / _wheel_name()

    file_entries = list(contents)
    dist_info = _dist_info_dir()
    file_entries.extend(
        [
            (f"{dist_info}/METADATA", _metadata()),
            (f"{dist_info}/WHEEL", _wheel_file()),
            (f"{dist_info}/entry_points.txt", _entry_points()),
        ]
    )
    file_entries.append((f"{dist_info}/RECORD", _record_rows(file_entries)))

    with zipfile.ZipFile(
        wheel_path,
        "w",
        compression=zipfile.ZIP_DEFLATED,
    ) as zf:
        for name, data in file_entries:
            zf.writestr(name, data)
    return wheel_path.name


def _write_metadata(metadata_directory: str) -> str:
    metadata_root = Path(metadata_directory)
    metadata_root.mkdir(parents=True, exist_ok=True)
    dist_info = metadata_root / _dist_info_dir()
    dist_info.mkdir(parents=True, exist_ok=True)
    (dist_info / "METADATA").write_bytes(_metadata())
    (dist_info / "WHEEL").write_bytes(_wheel_file())
    (dist_info / "entry_points.txt").write_bytes(_entry_points())
    return dist_info.name


def _iter_sdist_files() -> Iterator[Path]:
    skip_parts = {
        ".git",
        ".pytest_cache",
        "__pycache__",
        ".mypy_cache",
        ".ruff_cache",
    }
    for path in sorted(ROOT.rglob("*")):
        if path.is_dir():
            continue
        if any(part in skip_parts for part in path.parts):
            continue
        yield path


